function validate([s1, s2]) {
  if (typeof s1 !== 'string' || typeof s2 !== 'string') return 's1 and s2 must be strings.';
  if (s1.length !== 4 || s2.length !== 4) return 'Both strings must have exactly 4 letters.';
  if (!/^[a-z]{4}$/.test(s1) || !/^[a-z]{4}$/.test(s2)) return 'Use only lowercase English letters.';
  return null;
}

