function canBeEqual(s1, s2) {
  // Exchanges never move a letter between even and odd positions, and they can arrange each pair freely.
  const pair = (s, start) => [s[start], s[start + 2]].sort().join('');
  return pair(s1, 0) === pair(s2, 0) && pair(s1, 1) === pair(s2, 1);
}

