function generate(rand, size) {
  const span = 1 + Math.floor(rand() * (size === 'large' ? 26 : 4));
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * span));
  const s1 = Array.from({ length: 4 }, letter).join('');
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [s1, Array.from({ length: 4 }, letter).join('')];
  // Shuffle s1's letters: either only within each parity (always reachable) or freely.
  const chars = s1.split('');
  const swap = (a, b) => { [chars[a], chars[b]] = [chars[b], chars[a]]; };
  if (rand() < 0.5) swap(0, 2);
  if (rand() < 0.5) swap(1, 3);
  if (mode === 2) swap(Math.floor(rand() * 4), Math.floor(rand() * 4));
  return [s1, chars.join('')];
}
